# %% [markdown]
# # Batter Profile
# *Single-hitter deep dive — generated by `statslab new-notebook batter-profile`.*

# %% tags=["parameters"]
player = "Aaron Judge"
season = None
start_date = None
end_date = None
recent_form_pas = 25

# %% tags=["setup"] jupyter={"source_hidden": true}
from IPython.display import Markdown, display

from mlb_stats_lab.batting import (
    batting_line,
    contact_quality,
    performance_by_pitch_type,
    plate_discipline,
    rolling_batting_line,
)
from mlb_stats_lab.batting.splits import splits as batting_splits
from mlb_stats_lab.data import current_season, get_statcast_batter, season_range
from mlb_stats_lab.reports.summary import batter_bullets
from mlb_stats_lab.viz import (
    ev_la_scatter,
    metric_row,
    report_header,
    rolling_metric_line,
    section,
    splits_bar_chart,
    spray_chart,
    stat_table,
    zone_grid,
    zone_heatmap,
)

season = season or current_season()
if start_date is None or end_date is None:
    s, e = season_range(season)
    start_date = start_date or s
    end_date = end_date or e

display(report_header(player, f"{season} season · {start_date} → {end_date}"))

# %% tags=["load"] jupyter={"source_hidden": true}
df = get_statcast_batter(player, start=start_date, end=end_date)
print(f"Loaded {len(df)} pitches for {player}.")

# %%
display(section("Season Line"))
line = batting_line(df)
disc = plate_discipline(df)
contact = contact_quality(df)
display(
    metric_row(
        {
            "PA": line.get("PA"),
            "AVG": line.get("AVG"),
            "OBP": line.get("OBP"),
            "SLG": line.get("SLG"),
            "wOBA": line.get("wOBA"),
            "HR": line.get("HR"),
        }
    )
)
display(stat_table(line, "Batting Line"))

# %%
display(section("Plate Discipline & Contact"))
display(stat_table(disc, "Discipline"))
display(stat_table(contact, "Contact Quality"))

# %%
display(section("Spray Chart"))
spray_chart(df, title=f"{player} — Batted Balls")

# %%
display(section("Zone Profile"))
zone_heatmap(df, metric="density", title="Pitches Seen")
zone_heatmap(df, metric="swing_rate", title="Swing Rate")
zone_grid(df, metric="xwoba", bins=3, title="xwOBA by Zone")

# %%
display(section("Contact Profile", "Exit velocity vs. launch angle"))
ev_la_scatter(df, color_by="outcome", overlay_barrel_zone=True, title="EV vs LA")

# %%
display(section("Splits"))
for axis, title in [("vs_hand", "vs Hand"), ("home_away", "Home/Away"), ("month", "Month")]:
    s = batting_splits(df, axis=axis)
    display(s)
    splits_bar_chart(s, metric="wOBA", title=title)

# %%
display(section("Performance by Pitch Type"))
display(performance_by_pitch_type(df))

# %%
display(section("Recent Form", f"Rolling over {recent_form_pas} PA"))
rolling = rolling_batting_line(df, window=recent_form_pas, over="PA")
rolling_metric_line(rolling, metric="wOBA", league_average=0.320, title="Rolling wOBA")

# %% tags=["summary"]
display(section("Takeaways"))
display(Markdown("\n".join(batter_bullets(line, disc, contact))))

